238	/**
239	 * Update the session data for the current request.
240	 */
241	export async function updateSession<T extends SessionData = SessionData>(
242	  event: HTTPEvent,
243	  config: SessionConfig,
244	  update?: SessionUpdate<T>,
245	): Promise<Session<T>> {
246	  const sessionName = config.name || DEFAULT_SESSION_NAME;
247	
248	  // Access current session
249	  const context = getEventContext<H3EventContext>(event);
250	  const session: Session<T> =
251	    (context.sessions?.[sessionName] as Session<T>) || (await getSession<T>(event, config));
252	
253	  // Update session data if provided
254	  if (typeof update === "function") {
255	    update = update(session.data);
256	  }
257	  if (update) {
258	    Object.assign(session.data, update);
259	  }
260	
261	  // Persisted (or persistence is disabled by config): no longer a fresh session
262	  // awaiting its first write.
263	  delete session[kSessionNew];
264	
265	  // Seal and store in cookie
266	  if (config.cookie !== false && (event as H3Event).res) {
267	    const sealed = await sealSession(event, config);
268	    setChunkedCookie(event as H3Event, sessionName, sealed, {
269	      ...DEFAULT_SESSION_COOKIE,
270	      expires: sessionExpires(session, config),
271	      ...config.cookie,
272	    });
273	    stageSessionErrCookies(event as H3Event, sessionName);
274	  }
275	
276	  return session;
277	}
